<?php

namespace Grav\Theme;

use Grav\Common\Page\Interfaces\PageInterface;
use Grav\Common\Theme;
use Grav\Common\Utils;
use RocketTheme\Toolbox\Event\Event;
use Twig\TwigFunction;

/**
 * __THEME_TITLE__ — generated by the website-to-grav skill.
 *
 * Owns the document shell (no parent theme), renders frontmatter `sections`, keeps preview
 * hosts out of search indexes and makes shared forms available on every page.
 */
class __ThemeClass__ extends Theme
{
    public static function getSubscribedEvents(): array
    {
        return [
            'onPagesInitialized' => ['onPagesInitialized', -10],
            'onPageHeaders' => ['onPageHeaders', 0],
            'onTwigInitialized' => ['onTwigInitialized', 0],
        ];
    }

    private function setting(string $key, $default = null)
    {
        return $this->grav['config']->get('themes.' . $this->name . '.' . $key, $default);
    }

    /** True for local/preview hosts that must never be indexed (crawlers still need access to see it). */
    public function isNoindexHost(): bool
    {
        $host = strtolower(rtrim((string) $this->grav['uri']->host(), '.'));

        return in_array($host, array_map('strtolower', (array) $this->setting('noindex_hosts', [])), true);
    }

    /** Analytics render only on the configured production hosts, never on local or preview copies. */
    public function analyticsAllowed(): bool
    {
        if (!$this->setting('analytics.enabled', false) || $this->isNoindexHost()) {
            return false;
        }
        $host = strtolower(rtrim((string) $this->grav['uri']->host(), '.'));
        $hosts = array_map('strtolower', (array) $this->setting('analytics.hosts', []));

        return !$hosts || in_array($host, $hosts, true);
    }

    public function onPageHeaders(Event $event): void
    {
        if ($this->isNoindexHost()) {
            $event['headers']->{'X-Robots-Tag'} = 'noindex, nofollow';
        }
    }

    /**
     * Forms defined on /forms/* pages are rendered on many other pages (footers, modals).
     * Grav's Form plugin learns definitions in onPageProcessed, which cached page trees can skip,
     * so replay it for the shared form pages before rendering or POST handling.
     */
    public function onPagesInitialized(Event $event): void
    {
        if ($this->isAdmin()) {
            return;
        }
        foreach ((array) $this->setting('shared_form_routes', []) as $route) {
            $page = $this->grav['pages']->find($route);
            if ($page && $page->published()) {
                $this->grav->fireEvent('onPageProcessed', new Event(['page' => $page]));
            }
        }
    }

    public function onTwigInitialized(): void
    {
        $twig = $this->grav['twig']->twig();
        $twig->addFunction(new TwigFunction('theme_media', [$this, 'media']));
        $twig->addFunction(new TwigFunction('shared_section_page', [$this, 'sharedSectionPage']));
        $twig->addFunction(new TwigFunction('theme_noindex', [$this, 'isNoindexHost']));
        $twig->addFunction(new TwigFunction('theme_analytics_allowed', [$this, 'analyticsAllowed']));
    }

    /**
     * Resolve a frontmatter media value: a page file name, a media:// / theme:// stream, or a URL.
     *
     * @return array{url: string, medium: mixed}|null
     */
    public function media(?string $value, ?PageInterface $page = null): ?array
    {
        if (!$value) {
            return null;
        }
        if (preg_match('#^(https?:)?//#i', $value) || str_starts_with($value, '/')) {
            return ['url' => $value, 'medium' => null];
        }
        $page = $page ?? $this->grav['page'];
        $medium = $page ? ($page->media()[$value] ?? null) : null;
        if ($medium) {
            return ['url' => $medium->url(), 'medium' => $medium];
        }
        $url = Utils::url($value);

        return $url ? ['url' => $url, 'medium' => null] : null;
    }

    /** The /shared/<name> page in the active language, used for repeated sections. */
    public function sharedSectionPage(string $name): ?PageInterface
    {
        $page = $this->grav['pages']->find('/shared/' . $name, true);

        return $page ?: null;
    }
}
